<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\AssignmentService;use App\Support\Url;Auth::requirePermission('ASSIGNMENT_QUEUE_VIEW');$queue=AssignmentService::queue();$all=Auth::can('ASSIGNMENT_VIEW_ALL')?AssignmentService::all():[];$pageTitle='Assignments';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Transport assignments</h1><p>Convert accepted winning offers into Operations-controlled assignments.</p></div><span class="badge"><?=h(count($queue))?> awaiting assignment</span></div><div class="notice">Assignment records the Carrier, truck and Driver and moves the load to assigned. Resources remain reserved. Dispatch is not created until Phase 8.</div><div class="card table-wrap"><h2>Accepted offers awaiting assignment</h2><table><thead><tr><th>Load</th><th>Carrier</th><th>Truck / Driver</th><th>Price TZS</th><th>Accepted UTC</th><th></th></tr></thead><tbody><?php foreach($queue as$r):?><tr><td><?=h($r['load_ref'].' · '.$r['origin_city'].' → '.$r['destination_city'])?></td><td><?=h($r['carrier_company_name']?:$r['carrier_user_name'])?></td><td><?=h($r['registration_number'].' · '.$r['driver_name'])?></td><td><?=h(number_format((float)$r['offered_amount_tzs'],2))?></td><td><?=h($r['responded_at'])?></td><td><a href="<?=h(Url::to('operations/assignment-create.php?offer_id='.$r['offer_id']))?>">Assign</a></td></tr><?php endforeach;if(!$queue):?><tr><td colspan="6" class="muted">No accepted offers are awaiting assignment.</td></tr><?php endif;?></tbody></table></div><div class="card table-wrap" style="margin-top:18px"><h2>Assignment history</h2><table><thead><tr><th>Assignment</th><th>Load</th><th>Carrier</th><th>Truck / Driver</th><th>Status</th><th>Assigned UTC</th><th></th></tr></thead><tbody><?php foreach($all as$r):?><tr><td><?=h($r['assignment_ref'])?></td><td><?=h($r['load_ref'])?></td><td><?=h($r['carrier_company_name']?:$r['carrier_user_name'])?></td><td><?=h($r['registration_number'].' · '.$r['driver_name'])?></td><td><span class="status-pill status-<?=h($r['assignment_status'])?>"><?=h(str_replace('_',' ',$r['assignment_status']))?></span></td><td><?=h($r['assigned_at'])?></td><td><a href="<?=h(Url::to('operations/assignment-view.php?id='.$r['assignment_id']))?>">Open</a></td></tr><?php endforeach;if(!$all):?><tr><td colspan="7" class="muted">No assignments.</td></tr><?php endif;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
